    option_b_hi: "\u0915\u093E\u0930\u094D\u092F\u092A\u093E\u0932\u093F\u0915\u093E \u0938\u0947 \u0928\u094D\u092F\u093E\u092F\u092A\u093E\u0932\u093F\u0915\u093E \u0915\u093E \u092A\u0943\u0925\u0915\u094D\u0915\u0930\u0923",
    option_c: "Separation of Centre from State",
    option_c_hi: "\u0915\u0947\u0902\u0926\u094D\u0930 \u0938\u0947 \u0930\u093E\u091C\u094D\u092F \u0915\u093E \u092A\u0943\u0925\u0915\u094D\u0915\u0930\u0923",
