    option_d_hi: "\u0926\u0940\u0935\u093E\u0928\u0940 \u0938\u0947 \u092B\u094C\u091C\u0926\u093E\u0930\u0940 \u0915\u093E\u0928\u0942\u0928 \u0915\u093E \u092A\u0943\u0925\u0915\u094D\u0915\u0930\u0923",
