    option_c_hi: "\u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0936\u0930\u094D\u091F \u092C\u093E\u0939\u0930 \u0930\u0916\u0928\u0947 \u0938\u0947 \u092A\u0947\u091F \u092E\u0947\u0902 \u0926\u0930\u094D\u0926 \u0939\u094B\u0924\u093E \u0939\u0948",
