    option_b_hi: "\u0924\u0941\u0930\u0902\u0924 \u092E\u0941\u0902\u0939 \u0938\u0947 \u0938\u093E\u0902\u0938 \u0926\u0947\u0928\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u093E",
