    option_d_hi: "\u0918\u093E\u092F\u0932 \u0915\u0940 \u091C\u0947\u092C \u0938\u0947 \u092A\u0939\u091A\u093E\u0928 \u092A\u0924\u094D\u0930 \u0916\u094B\u091C\u0928\u093E",
